async function lockGen5Plan(){let x=state();if(x.gen5.planLocked)return x;if(x.gen5.planHash!==PLAN_HASH)throw Error('BLOCKERAD: Gen5-planens hash matchar inte det granskade förslaget');const at=new Date().toISOString();x.gen5.planLocked=true;x.gen5.planLockedAt=at;x.gen5.state='PLAN_LOCKED_RUNNERSPEC_NOT_BUILT';x=save(x);try{const E=window.LinaEvidence;if(E?.stage&&E?.approveAndSync){const artifact={schema:'LINA-GEN5-PLAN-EVIDENCE-1',release:VERSION,createdAt:at,planHash:PLAN_HASH,plan:GEN5_PLAN,tradeEnabled:false,forward:'NOT OPENED'};const item=E.stage(`LINAS_GEN5_PLAN_LOCK_${at.slice(0,10)}.json`,JSON.stringify(artifact,null,2),'application/json','Lina Generation Engine');if(item?.id){const r=await E.approveAndSync(item.id);x=state();x.gen5.evidence={status:r?.status||'FROZEN',githubPath:r?.githubPath||null,githubCommit:r?.githubCommit||null};save(x)}}}catch(e){x=state();x.gen5.evidence={status:'FROZEN · VÄNTAR PÅ SYNK',syncError:String(e?.message||e)};save(x)}return state()}
async function lockGen6Plan(){let x=state();if(x.gen6.planLocked)return x;if(x.gen6.planHash!==GEN6_PLAN_PROPOSAL_HASH)throw Error('BLOCKERAD: Gen6-planens hash matchar inte det godkända förslaget');if(!x.gen5.summaryFreeze?.frozen)throw Error('BLOCKERAD: Gen5 är inte fryst');const at=new Date().toISOString();x.gen6.planLocked=true;x.gen6.planLockedAt=at;x.gen6.state='PLAN_LOCKED_RUNNERSPEC_NOT_BUILT';x=save(x);try{const E=window.LinaEvidence;if(E?.stage&&E?.approveAndSync){const plan={...GEN6_PLAN_PROPOSAL,decision:'APPROVED_AND_LOCKED'};const artifact={schema:'LINA-GEN6-PLAN-EVIDENCE-1',release:VERSION,createdAt:at,planHash:GEN6_PLAN_PROPOSAL_HASH,plan,sourceGeneration:5,tradeEnabled:false,forward:'NOT OPENED',immutable:true};const item=E.stage(`LINAS_GEN6_PLAN_LOCK_${at.slice(0,10)}.json`,JSON.stringify(artifact,null,2),'application/json','Lina Generation Engine');if(item?.id){const r=await E.approveAndSync(item.id);x=state();x.gen6.evidence={status:r?.status||'FROZEN',name:item.name||null,githubPath:r?.githubPath||null,githubCommit:r?.githubCommit||null};save(x)}}}catch(e){x=state();x.gen6.evidence={status:'FROZEN · VÄNTAR PÅ SYNK',syncError:String(e?.message||e)};save(x)}return state()}
