async function lockGen8Plan(){let x=state();if(!x.gen8)throw Error('BLOCKERAD: Gen8-underlag saknas');if(x.gen8.planLocked)return x;if(x.gen8.planHash!==GEN8_PLAN_PROPOSAL_HASH)throw Error('BLOCKERAD: Gen8-planens hash matchar inte det godkända förslaget');if(!x.gen7.summaryFreeze?.frozen||!x.gen7.gen8Basis||!gen7Integrity().ok)throw Error('BLOCKERAD: Gen7 måste vara fryst och integritetsgrön');const at=new Date().toISOString();x.gen8.planLocked=true;x.gen8.planLockedAt=at;x.gen8.state='PLAN_LOCKED_RUNNERSPEC_NOT_BUILT';x=save(x);try{const E=window.LinaEvidence;if(E?.stage&&E?.approveAndSync){const plan={...GEN8_PLAN_PROPOSAL,decision:'APPROVED_AND_LOCKED'};const artifact={schema:'LINA-GEN8-PLAN-EVIDENCE-1',release:VERSION,createdAt:at,planHash:GEN8_PLAN_PROPOSAL_HASH,plan,sourceGeneration:7,tradeEnabled:false,forward:'NOT OPENED',immutable:true};const item=E.stage(`LINAS_GEN8_PLAN_LOCK_${at.slice(0,10)}.json`,JSON.stringify(artifact,null,2),'application/json','Lina Generation Engine');if(item?.id){const r=await E.approveAndSync(item.id);x=state();x.gen8.evidence={status:r?.status||'FROZEN',name:item.name||null,githubPath:r?.githubPath||null,githubCommit:r?.githubCommit||null};save(x)}}}catch(e){x=state();x.gen8.evidence={status:'FROZEN · VÄNTAR PÅ SYNK',syncError:String(e?.message||e)};save(x)}return state()}
async function syncGen8Evidence(onStatus){const E=window.LinaEvidence,x=state();if(!x.gen8?.summaryFreeze?.frozen)throw Error('BLOCKERAD: Gen8 är inte fryst');const say=t=>{try{onStatus?.(t)}catch{}};say('Synkar endast redan fryst Gen8-evidens');await E.syncApproved();E.reconcileAll?.();const y=state(),families=window.LinaGen8Engine?.FAMILIES||[],fr=y.gen8.familyResults||{};const ok=families.length===4&&families.every(f=>githubOk(fr[f]?.evidence))&&githubOk(y.gen8.summaryFreeze?.evidence)&&(!y.gen8.candidate?.locked||githubOk(y.gen8.candidate?.evidence));if(!ok)throw Error('Gen8 är fryst men all evidens är ännu inte GitHub-verifierad');say('KLART · Gen8 FROZEN · GITHUB ✓');return{ok:true,state:y}}

function registry(){const x=state(),gens=[gen4Snapshot(),{generation:5,label:'Generation 5',state:x.gen5.state,planHash:PLAN_HASH,runnerSpecHash:x.gen5.runnerSpecHash,candidate:x.gen5.candidate,immutable:Boolean(x.gen5.planLocked),source:'Lärdomsunderlag från fryst Gen4',basis:gen5Basis(),plan:GEN5_PLAN,planLock:{locked:x.gen5.planLocked,lockedAt:x.gen5.planLockedAt,evidence:x.gen5.evidence}},{generation:6,label:'Generation 6',state:x.gen6.state,planHash:GEN6_PLAN_PROPOSAL_HASH,runnerSpecHash:x.gen6.runnerSpecHash,candidate:x.gen6.candidate,immutable:Boolean(x.gen6.planLocked),source:'Fryst Gen5-underlag',plan:{...GEN6_PLAN_PROPOSAL,decision:x.gen6.planLocked?'APPROVED_AND_LOCKED':'HUMAN_APPROVED_AWAITING_LOCK'},planLock:{locked:x.gen6.planLocked,lockedAt:x.gen6.planLockedAt,evidence:x.gen6.evidence}},{generation:7,label:'Generation 7',state:x.gen7.state,planHash:GEN7_PLAN_PROPOSAL_HASH,runnerSpecHash:x.gen7.runnerSpecHash,candidate:x.gen7.candidate,immutable:Boolean(x.gen7.planLocked),source:'Fryst Gen6-underlag',basis:x.gen6.gen7Basis||null,plan:{...GEN7_PLAN_PROPOSAL,decision:x.gen7.planLocked?'APPROVED_AND_LOCKED':'REVIEWED_READY_FOR_AUTO_PIPELINE'},planLock:{locked:x.gen7.planLocked,lockedAt:x.gen7.planLockedAt,evidence:x.gen7.evidence}}];if(x.gen7?.gen8Basis&&gen7Integrity().ok)gens.push({generation:8,label:'Generation 8',state:x.gen8?.state||'PLAN_APPROVED_AWAITING_LOCK',planHash:GEN8_PLAN_PROPOSAL_HASH,runnerSpecHash:x.gen8?.runnerSpecHash||null,candidate:x.gen8?.candidate||null,immutable:Boolean(x.gen8?.planLocked),source:'Fryst och integritetsverifierat Gen7-underlag',basis:x.gen7.gen8Basis,plan:{...GEN8_PLAN_PROPOSAL,decision:x.gen8?.planLocked?'APPROVED_AND_LOCKED':'HUMAN_APPROVED_AWAITING_AUTO_PIPELINE'},planLock:{locked:Boolean(x.gen8?.planLocked),lockedAt:x.gen8?.planLockedAt||null,evidence:x.gen8?.evidence||null}});return{schema:SCHEMA,release:VERSION,tradeEnabled:false,generations:gens}}
